create or replace function private.ensure_hierarchy_producer(
    p_key text,
    p_name text
)
returns uuid
language plpgsql
security definer
set search_path = ''
as $function$
declare
    v_ids uuid[];
    v_id uuid;
begin
    select array_agg(producer.id order by producer.id) into v_ids
    from public.wine_reference_producers producer
    where private.normalize_wine_reference_text(producer.canonical_name) =
          private.normalize_wine_reference_text(p_name);

    if cardinality(v_ids) > 1 then
        raise exception using
            errcode = '21000',
            message = format('Canonical producer %s is ambiguous', p_name);
    elsif cardinality(v_ids) = 1 then
        return v_ids[1];
    end if;

    v_id := private.enrichment_seed_uuid('wine-reference:producer:' || p_key);
    insert into public.wine_reference_entities (id, entity_type)
    values (v_id, 'producer') on conflict (id) do nothing;
    insert into public.wine_reference_producers (id, canonical_name)
    values (v_id, p_name) on conflict (id) do nothing;
    return v_id;
end;
$function$;

create or replace function private.ensure_hierarchy_product(
    p_key text,
    p_producer_id uuid,
    p_name text
)
returns uuid
language plpgsql
security definer
set search_path = ''
as $function$
declare
    v_ids uuid[];
    v_id uuid;
begin
    select array_agg(product.id order by product.id) into v_ids
    from public.wine_reference_products product
    where product.producer_id = p_producer_id
      and private.normalize_wine_reference_text(product.canonical_name) =
          private.normalize_wine_reference_text(p_name);

    if cardinality(v_ids) > 1 then
        raise exception using
            errcode = '21000',
            message = format('Canonical product %s is ambiguous', p_name);
    elsif cardinality(v_ids) = 1 then
        return v_ids[1];
    end if;

    v_id := private.enrichment_seed_uuid('wine-reference:product:' || p_key);
    insert into public.wine_reference_entities (id, entity_type)
    values (v_id, 'product') on conflict (id) do nothing;
    insert into public.wine_reference_products (id, producer_id, canonical_name)
    values (v_id, p_producer_id, p_name) on conflict (id) do nothing;
    return v_id;
end;
$function$;

