create or replace function private.link_hierarchy_profile_evidence(
    p_profile_id uuid,
    p_source_key text,
    p_claim_type text,
    p_scope_level text,
    p_place_id uuid default null,
    p_producer_id uuid default null,
    p_product_id uuid default null,
    p_release_id uuid default null,
    p_vintage_year integer default null,
    p_wine_color text default null
)
returns void
language plpgsql
security definer
set search_path = ''
as $function$
declare
    v_source_id uuid;
    v_policy_id uuid;
    v_evidence_id uuid := private.enrichment_seed_uuid(
        'evidence:maturity-v3:' || p_profile_id::text || ':' || p_source_key
    );
    v_url text;
begin
    select source.id, source.homepage_url into v_source_id, v_url
    from public.enrichment_sources source where source.source_key = p_source_key;
    if not found then
        raise exception using errcode = '23503',
            message = format('Unknown hierarchy source %s', p_source_key);
    end if;

    select policy.id into v_policy_id
    from public.enrichment_source_policies policy
    where policy.source_id = v_source_id and policy.policy_version = 1;

    insert into public.enrichment_evidence (
        id, source_id, source_policy_id, source_record_id, source_record_url,
        content_mode, claim_type, scope_level, place_id, producer_id,
        product_id, release_id, vintage_year, wine_color,
        review_status, reviewed_at, source_published_on
    )
    values (
        v_evidence_id, v_source_id, v_policy_id,
        'maturity-v3:' || p_profile_id::text, v_url,
        'pointer-only', p_claim_type, p_scope_level, p_place_id, p_producer_id,
        p_product_id, p_release_id, p_vintage_year, p_wine_color,
        'reviewed', '2026-08-24T09:00:00Z', '2026-08-24'
    )
    on conflict (id) do nothing;

    insert into public.enrichment_profile_evidence (
        profile_id, evidence_id, evidence_role
    ) values (p_profile_id, v_evidence_id, 'supports')
    on conflict do nothing;
end;
$function$;

