"color":"red","firstVintage":2023,"finalVintage":2023,"windowAdjustment":{"first":0,"bestStart":0,"bestEnd":0,"outer":0},"traits":{"acidity":0.2,"tannin":-0.1,"freshness":0.3},"interactions":[],"confidence":0.76,"evidence":["cal-demoura-official","owner-workbook-cal-demoura"],"rationale":"The producer describes balance, freshness and fine tannins across distinct landscape and parcel wines; the POC deliberately limits this profile to the reviewed vintage."}],"cuvees":[{"id":"les-evocelles-louis-boillot","producerKey":"louis-boillot","placeId":"les-evocelles","name":"Gevrey-Chambertin Les Evocelles","aliases":["Evocelles","Les Evocelles"],"color":"red","windowAdjustment":{"first":0,"bestStart":0,"bestEnd":0,"outer":0},"traits":{"concentration":0.2,"freshness":0.1},"confidence":0.74,"evidence":["boillot-vertical","boillot-evocelles-2017"],"rationale":"Old vines and recurring observations of tension, fine tannins and mineral freshness support the exact cuvee identity."},{"id":"terres-de-jonquieres-cal-demoura","producerKey":"cal-demoura","placeId":"terrasses-du-larzac","name":"Terres de Jonquières","aliases":["Terres de Jonquieres","Terres de Jonquières","Terre de Jonquières"],"color":"red","windowAdjustment":{"first":0,"bestStart":0,"bestEnd":-3,"outer":-3},"traits":{"body":-0.2,"tannin":-0.3,"freshness":0.2,"concentration":-0.2},"confidence":0.78,"evidence":["cal-demoura-official","owner-workbook-cal-demoura"],"rationale":"A balanced multi-site blend with pure fruit and fine tannins is the earliest reviewed red in the 2023 range."},{"id":"combariolles-cal-demoura","producerKey":"cal-demoura","placeId":"terrasses-du-larzac","name":"Les Combariolles","aliases":["Combariolles","Les Combariolles"],"color":"red","windowAdjustment":{"first":2,"bestStart":3,"bestEnd":1,"outer":2},"traits":{"body":0.3,"acidity":0.3,"tannin":0.3,"freshness":0.2,"concentration":0.6},"confidence":0.8,"evidence":["cal-demoura-official","owner-workbook-cal-demoura"],"rationale":"The limestone parcel's density, vertical energy and depth justify a later central period than the landscape blend."},{"id":"belle-fiolle-cal-demoura","producerKey":"cal-demoura","placeId":"terrasses-du-larzac","name":"Belle Fiolle","aliases":["Belle Fiolle"],"color":"red","windowAdjustment":{"first":0,"bestStart":0,"bestEnd":-1,"outer":0},"traits":{"body":-0.3,"acidity":0.1,"tannin":-0.4,"freshness":0.3,"concentration":-0.2},"confidence":0.76,"evidence":["cal-demoura-official","owner-workbook-cal-demoura"],"rationale":"Cinsault-led elegance, freshness and perfume support an earlier, less tannic central period."},{"id":"feu-sacre-cal-demoura","producerKey":"cal-demoura","placeId":"terrasses-du-larzac","name":"Feu Sacré","aliases":["Feu Sacre","Feu Sacré"],"color":"red","windowAdjustment":{"first":4,"bestStart":6,"bestEnd":7,"outer":7},"traits":{"body":0.5,"acidity":0.2,"tannin":0.3,"freshness":0.2,"concentration":0.8},"confidence":0.82,"evidence":["cal-demoura-official","owner-workbook-cal-demoura"],"rationale":"Old Grenache generosity is balanced by site freshness and explicitly described as having very high potential."},{"id":"fragments-cal-demoura","producerKey":"cal-demoura","placeId":"terrasses-du-larzac","name":"Fragments","aliases":["Fragments"],"color":"red","windowAdjustment":{"first":5,"bestStart":8,"bestEnd":9,"outer":10},"traits":{"body":0.6,"acidity":0.5,"tannin":0.7,"freshness":0.5,"concentration":0.8},"confidence":0.82,"evidence":["cal-demoura-official","owner-workbook-cal-demoura"],"rationale":"The northern old-vine Syrah parcel is intense, structured and explicitly described by the producer as requiring patience."}],"releases":[{"id":"les-evocelles-louis-boillot-2021","producerKey":"louis-boillot","cuveeId":"les-evocelles-louis-boillot","name":"Les Evocelles 2021","vintage":2021,"windowAdjustment":{"first":0,"bestStart":0,"bestEnd":-2,"outer":-3},"traits":{"concentration":-0.3},"confidence":0.8,"evidence":["boillot-evocelles-2021","owner-workbook-boillot"],"rationale":"Frost, coulure and hail sharply reduced the crop; published assessments describe an earlier, shorter-lived expression."}]}$knowledge$::jsonb;
    v_source record;
    v_place record;
    v_vintage record;
    v_producer record;
    v_interaction record;
    v_cuvee record;
    v_release record;
    v_source_key text;
    v_source_id uuid;
    v_policy_id uuid;
    v_place_id uuid;
    v_parent_id uuid;
    v_producer_id uuid;
    v_product_id uuid;
    v_release_id uuid;
    v_profile_id uuid;
    v_producer_profile_id uuid;
    v_cuvee_json jsonb;
    v_result jsonb;
begin
    if exists (
        select 1 from public.enrichment_knowledge_versions version
        where version.id = v_version_id
          and version.status in ('active', 'superseded', 'retired')
    ) then
        select jsonb_build_object(
            'knowledge_version_id', version.id,
            'status', version.status,
            'content_sha256', version.content_sha256,
            'already_installed', true
        ) into v_result
        from public.enrichment_knowledge_versions version
        where version.id = v_version_id;
        return v_result;
    end if;

    if exists (
        select 1 from public.enrichment_knowledge_versions version
        where version.version_number = 3 and version.id <> v_version_id
    ) then
        raise exception using errcode = '23505',
            message = 'Knowledge version 3 is already used by another model';
    end if;

    perform public.install_expanded_maturity_knowledge();

    insert into public.enrichment_knowledge_versions (
        id, version_number, label, model_key, model_version
    ) values (
        v_version_id, 3, 'Hierarchical maturity model — reviewed proof of concept',
        'hierarchical-maturity', 'hierarchy-poc-1.0.0'
    ) on conflict (id) do nothing;

    for v_source in
        select value ->> 'id' as key, value ->> 'name' as name,
               value ->> 'kind' as kind, value ->> 'url' as url
        from jsonb_array_elements(v_knowledge -> 'sources') seed(value)
    loop
        select source.id into v_source_id
        from public.enrichment_sources source where source.source_key = v_source.key;
        if not found then
            v_source_id := private.enrichment_seed_uuid('source:maturity-v3:' || v_source.key);
            insert into public.enrichment_sources (
                id, source_key, source_name, source_kind, homepage_url
            ) values (
                v_source_id, v_source.key, v_source.name,
                case
                    when v_source.kind like 'private-owner%' then 'owner'
                    when v_source.kind like 'official-vintage%' then 'vintage-report'
                    when v_source.kind like 'official-place%' then 'regulatory'
                    when v_source.kind like 'producer%' then 'producer'
                    else 'critic'
                end,
                nullif(v_source.url, '')
            );
        end if;

        select policy.id into v_policy_id
        from public.enrichment_source_policies policy
        where policy.source_id = v_source_id and policy.policy_version = 1;
        if not found then
            v_policy_id := private.enrichment_seed_uuid('policy:maturity-v3:' || v_source.key);
            insert into public.enrichment_source_policies (
                id, source_id, policy_version, status, effective_from, notes
            ) values (
                v_policy_id, v_source_id, 1, 'draft', '2026-08-24',
                'Pointer-only evidence. The reviewed CellarManager profile stores derived model parameters, not copied source text.'
            );
        end if;
    end loop;

    -- Preserve v2 coverage, excluding only layers replaced by reviewed v3
    -- equivalents. Profile IDs change so v2 remains immutable and inspectable.
    insert into public.enrichment_profiles (
        id, knowledge_version_id, profile_type, review_status,
        confidence, rationale, reviewed_by, reviewed_at
    )
    select
        private.enrichment_seed_uuid('profile:maturity-v3:copy:' || profile.id::text),
        v_version_id, profile.profile_type, profile.review_status,
        profile.confidence, profile.rationale, profile.reviewed_by, profile.reviewed_at
    from public.enrichment_profiles profile
    left join public.enrichment_place_profiles place on place.profile_id = profile.id
    left join public.enrichment_vintage_profiles vintage on vintage.profile_id = profile.id
    where profile.knowledge_version_id = v_v2_id
      and not (
          profile.profile_type = 'place'
          and place.place_id in (
              private.enrichment_seed_uuid('place:bourgogne'),
              private.enrichment_seed_uuid('place:languedoc')
          )
          and place.wine_color = 'red'
      )
      and not (
          profile.profile_type = 'vintage'
          and vintage.wine_color = 'red'
          and (
              (vintage.place_id = private.enrichment_seed_uuid('place:bourgogne')
               and vintage.vintage_year between 2017 and 2022)
              or (vintage.place_id = private.enrichment_seed_uuid('place:languedoc')
                  and vintage.vintage_year = 2023)
          )
      );

    insert into public.enrichment_place_profiles (
        profile_id, knowledge_version_id, place_id, wine_color,
        first_trial_age, best_start_age, best_end_age, outer_horizon_age,
        body, acidity, tannin, sweetness, alcohol, freshness, savory, concentration
    )
    select
        private.enrichment_seed_uuid('profile:maturity-v3:copy:' || typed.profile_id::text),
        v_version_id, typed.place_id, typed.wine_color,
        typed.first_trial_age, typed.best_start_age, typed.best_end_age, typed.outer_horizon_age,
        typed.body, typed.acidity, typed.tannin, typed.sweetness,
        typed.alcohol, typed.freshness, typed.savory, typed.concentration
    from public.enrichment_place_profiles typed
    where typed.knowledge_version_id = v_v2_id
      and exists (
          select 1 from public.enrichment_profiles copied
          where copied.id = private.enrichment_seed_uuid('profile:maturity-v3:copy:' || typed.profile_id::text)
      );

    insert into public.enrichment_vintage_profiles (
        profile_id, knowledge_version_id, place_id, vintage_year, wine_color,
        first_trial_age_adjustment, best_start_age_adjustment,
        best_end_age_adjustment, outer_horizon_age_adjustment,
        body_adjustment, acidity_adjustment, tannin_adjustment,
        sweetness_adjustment, alcohol_adjustment, freshness_adjustment,
        savory_adjustment, concentration_adjustment, condition_tags
    )
    select
        private.enrichment_seed_uuid('profile:maturity-v3:copy:' || typed.profile_id::text),
        v_version_id, typed.place_id, typed.vintage_year, typed.wine_color,
        typed.first_trial_age_adjustment, typed.best_start_age_adjustment,
        typed.best_end_age_adjustment, typed.outer_horizon_age_adjustment,
        typed.body_adjustment, typed.acidity_adjustment, typed.tannin_adjustment,
        typed.sweetness_adjustment, typed.alcohol_adjustment,
        typed.freshness_adjustment, typed.savory_adjustment,
        typed.concentration_adjustment, typed.condition_tags
    from public.enrichment_vintage_profiles typed
    where typed.knowledge_version_id = v_v2_id
      and exists (
          select 1 from public.enrichment_profiles copied
          where copied.id = private.enrichment_seed_uuid('profile:maturity-v3:copy:' || typed.profile_id::text)
      );

    insert into public.enrichment_profile_evidence (profile_id, evidence_id, evidence_role)
    select
        private.enrichment_seed_uuid('profile:maturity-v3:copy:' || link.profile_id::text),
        link.evidence_id, link.evidence_role
    from public.enrichment_profile_evidence link
    where exists (
        select 1 from public.enrichment_profiles copied
        where copied.id = private.enrichment_seed_uuid('profile:maturity-v3:copy:' || link.profile_id::text)
    );

    for v_place in
        select value ->> 'id' as key, value ->> 'parentId' as parent,
               value ->> 'type' as type, value ->> 'name' as name,
               value -> 'aliases' as aliases, value ->> 'color' as color,
               value -> 'window' as window, value -> 'windowAdjustment' as adjustment,
               value -> 'traits' as traits, (value ->> 'confidence')::numeric as confidence,
               value ->> 'rationale' as rationale, value -> 'evidence' as evidence
        from jsonb_array_elements(v_knowledge -> 'places') with ordinality seed(value, position)
        order by position
    loop
        v_place_id := private.enrichment_seed_uuid('place:' || v_place.key);
        v_parent_id := case when v_place.parent is null then null
                            else private.enrichment_seed_uuid('place:' || v_place.parent) end;
        insert into public.enrichment_places (
            id, parent_id, place_type, canonical_name, country_code
        ) values (v_place_id, v_parent_id, v_place.type, v_place.name, 'FR')
        on conflict (id) do nothing;
        insert into public.enrichment_place_aliases (place_id, alias_value)
        select v_place_id, alias.value
        from jsonb_array_elements_text(v_place.aliases) alias(value)
        on conflict (normalized_value) do nothing;

        v_profile_id := private.enrichment_seed_uuid('profile:maturity-v3:place:' || v_place.key || ':' || v_place.color);
        insert into public.enrichment_profiles (
            id, knowledge_version_id, profile_type, review_status,
            confidence, rationale, reviewed_at
        ) values (
            v_profile_id, v_version_id,
            case when v_place.parent is null then 'place' else 'place-adjustment' end,
            'reviewed', v_place.confidence, v_place.rationale, '2026-08-24T09:00:00Z'
        );

        if v_place.parent is null then
            insert into public.enrichment_place_profiles (
                profile_id, knowledge_version_id, place_id, wine_color,
                first_trial_age, best_start_age, best_end_age, outer_horizon_age,
                body, acidity, tannin, sweetness, alcohol, freshness, savory, concentration
            ) values (
                v_profile_id, v_version_id, v_place_id, v_place.color,
                (v_place.window ->> 'first')::integer,
                (v_place.window ->> 'bestStart')::integer,
                (v_place.window ->> 'bestEnd')::integer,
                (v_place.window ->> 'outer')::integer,
                coalesce((v_place.traits ->> 'body')::numeric, 0),
                coalesce((v_place.traits ->> 'acidity')::numeric, 0),
                coalesce((v_place.traits ->> 'tannin')::numeric, 0),
                coalesce((v_place.traits ->> 'sweetness')::numeric, 0),
                coalesce((v_place.traits ->> 'alcohol')::numeric, 0),
                coalesce((v_place.traits ->> 'freshness')::numeric, 0),
                coalesce((v_place.traits ->> 'savory')::numeric, 0),
                coalesce((v_place.traits ->> 'concentration')::numeric, 0)
            );
        else
            insert into public.enrichment_place_adjustment_profiles (
                profile_id, knowledge_version_id, place_id, wine_color,
                first_trial_age_adjustment, best_start_age_adjustment,
                best_end_age_adjustment, outer_horizon_age_adjustment,
                body_adjustment, acidity_adjustment, tannin_adjustment,
                sweetness_adjustment, alcohol_adjustment, freshness_adjustment,
                savory_adjustment, concentration_adjustment
            ) values (
                v_profile_id, v_version_id, v_place_id, v_place.color,
                (v_place.adjustment ->> 'first')::integer,
                (v_place.adjustment ->> 'bestStart')::integer,
                (v_place.adjustment ->> 'bestEnd')::integer,
                (v_place.adjustment ->> 'outer')::integer,
                coalesce((v_place.traits ->> 'body')::numeric, 0),
                coalesce((v_place.traits ->> 'acidity')::numeric, 0),
                coalesce((v_place.traits ->> 'tannin')::numeric, 0),
                coalesce((v_place.traits ->> 'sweetness')::numeric, 0),
                coalesce((v_place.traits ->> 'alcohol')::numeric, 0),
                coalesce((v_place.traits ->> 'freshness')::numeric, 0),
                coalesce((v_place.traits ->> 'savory')::numeric, 0),
                coalesce((v_place.traits ->> 'concentration')::numeric, 0)
            );
        end if;

        for v_source_key in select jsonb_array_elements_text(v_place.evidence)
        loop
            perform private.link_hierarchy_profile_evidence(
                v_profile_id, v_source_key, 'wine-structure', 'place',
                p_place_id => v_place_id, p_wine_color => v_place.color
            );
        end loop;
    end loop;

    for v_vintage in
        select value ->> 'id' as key, value ->> 'placeId' as place,
               value ->> 'color' as color, (value ->> 'vintage')::integer as vintage,
               value -> 'tags' as tags, value -> 'windowAdjustment' as adjustment,
               value -> 'traits' as traits, (value ->> 'confidence')::numeric as confidence,
               value ->> 'rationale' as rationale, value -> 'evidence' as evidence
        from jsonb_array_elements(v_knowledge -> 'vintages') seed(value)
    loop
        v_place_id := private.enrichment_seed_uuid('place:' || v_vintage.place);
        v_profile_id := private.enrichment_seed_uuid('profile:maturity-v3:vintage:' || v_vintage.key);
        insert into public.enrichment_profiles (
            id, knowledge_version_id, profile_type, review_status,
            confidence, rationale, reviewed_at
        ) values (v_profile_id, v_version_id, 'vintage', 'reviewed',
                  v_vintage.confidence, v_vintage.rationale, '2026-08-24T09:00:00Z');
        insert into public.enrichment_vintage_profiles (
            profile_id, knowledge_version_id, place_id, vintage_year, wine_color,
            condition_tags, first_trial_age_adjustment, best_start_age_adjustment,
            best_end_age_adjustment, outer_horizon_age_adjustment,
            body_adjustment, acidity_adjustment, tannin_adjustment,
            sweetness_adjustment, alcohol_adjustment, freshness_adjustment,
            savory_adjustment, concentration_adjustment
        ) values (
            v_profile_id, v_version_id, v_place_id, v_vintage.vintage, v_vintage.color,
            array(select jsonb_array_elements_text(v_vintage.tags)),
            (v_vintage.adjustment ->> 'first')::integer,
            (v_vintage.adjustment ->> 'bestStart')::integer,
            (v_vintage.adjustment ->> 'bestEnd')::integer,
            (v_vintage.adjustment ->> 'outer')::integer,
            coalesce((v_vintage.traits ->> 'body')::numeric, 0),
            coalesce((v_vintage.traits ->> 'acidity')::numeric, 0),
            coalesce((v_vintage.traits ->> 'tannin')::numeric, 0),
            coalesce((v_vintage.traits ->> 'sweetness')::numeric, 0),
            coalesce((v_vintage.traits ->> 'alcohol')::numeric, 0),
            coalesce((v_vintage.traits ->> 'freshness')::numeric, 0),
            coalesce((v_vintage.traits ->> 'savory')::numeric, 0),
            coalesce((v_vintage.traits ->> 'concentration')::numeric, 0)
        );
        for v_source_key in select jsonb_array_elements_text(v_vintage.evidence)
        loop
            perform private.link_hierarchy_profile_evidence(
                v_profile_id, v_source_key, 'vintage-conditions', 'vintage',
                p_place_id => v_place_id, p_vintage_year => v_vintage.vintage,
                p_wine_color => v_vintage.color
            );
        end loop;
    end loop;

    for v_producer in
        select value ->> 'id' as key, value ->> 'producerKey' as producer_key,
               value ->> 'name' as name, value -> 'aliases' as aliases,
               value ->> 'color' as color,
               (value ->> 'firstVintage')::integer as first_vintage,
               coalesce((value ->> 'finalVintage')::integer, 2200) as final_vintage,
               value -> 'windowAdjustment' as adjustment, value -> 'traits' as traits,
               value -> 'interactions' as interactions,
               (value ->> 'confidence')::numeric as confidence,
               value ->> 'rationale' as rationale, value -> 'evidence' as evidence
        from jsonb_array_elements(v_knowledge -> 'producerEras') seed(value)
    loop
        v_producer_id := private.ensure_hierarchy_producer(
            v_producer.producer_key,
            case when v_producer.producer_key = 'louis-boillot' then 'Louis Boillot'
                 when v_producer.producer_key = 'cal-demoura' then 'Mas Cal Demoura'
                 else v_producer.name end
        );
        v_profile_id := private.enrichment_seed_uuid('profile:maturity-v3:producer:' || v_producer.key);
        insert into public.enrichment_profiles (
            id, knowledge_version_id, profile_type, review_status,
            confidence, rationale, reviewed_at
        ) values (v_profile_id, v_version_id, 'producer-era', 'reviewed',
                  v_producer.confidence, v_producer.rationale, '2026-08-24T09:00:00Z');
        insert into public.enrichment_producer_era_profiles (
            profile_id, knowledge_version_id, producer_id,
            first_vintage_year, final_vintage_year, wine_color,
            first_trial_age_adjustment, best_start_age_adjustment,
            best_end_age_adjustment, outer_horizon_age_adjustment,
            body_adjustment, acidity_adjustment, tannin_adjustment,
            sweetness_adjustment, alcohol_adjustment, freshness_adjustment,
            savory_adjustment, concentration_adjustment
        ) values (
            v_profile_id, v_version_id, v_producer_id,
            v_producer.first_vintage, v_producer.final_vintage, v_producer.color,
            (v_producer.adjustment ->> 'first')::integer,
            (v_producer.adjustment ->> 'bestStart')::integer,
            (v_producer.adjustment ->> 'bestEnd')::integer,
            (v_producer.adjustment ->> 'outer')::integer,
            coalesce((v_producer.traits ->> 'body')::numeric, 0),
            coalesce((v_producer.traits ->> 'acidity')::numeric, 0),
            coalesce((v_producer.traits ->> 'tannin')::numeric, 0),
            coalesce((v_producer.traits ->> 'sweetness')::numeric, 0),
            coalesce((v_producer.traits ->> 'alcohol')::numeric, 0),
            coalesce((v_producer.traits ->> 'freshness')::numeric, 0),
            coalesce((v_producer.traits ->> 'savory')::numeric, 0),
            coalesce((v_producer.traits ->> 'concentration')::numeric, 0)
        );
        for v_source_key in select jsonb_array_elements_text(v_producer.evidence)
        loop
            perform private.link_hierarchy_profile_evidence(
                v_profile_id, v_source_key, 'producer-style', 'producer',
                p_producer_id => v_producer_id, p_wine_color => v_producer.color
            );
        end loop;

        for v_interaction in
            select position::integer as position, value ->> 'label' as label,
                   value -> 'tagsAll' as tags, value -> 'windowAdjustment' as adjustment,
                   value -> 'traits' as traits, value ->> 'rationale' as rationale
            from jsonb_array_elements(v_producer.interactions) with ordinality seed(value, position)
        loop
            v_producer_profile_id := v_profile_id;
            v_profile_id := private.enrichment_seed_uuid(
                format('profile:maturity-v3:interaction:%s:%s', v_producer.key, v_interaction.position)
            );
            insert into public.enrichment_profiles (
                id, knowledge_version_id, profile_type, review_status,
                confidence, rationale, reviewed_at
            ) values (v_profile_id, v_version_id, 'producer-vintage-interaction',
                      'reviewed', v_producer.confidence, v_interaction.rationale, '2026-08-24T09:00:00Z');
            insert into public.enrichment_producer_vintage_interaction_profiles (
                profile_id, knowledge_version_id, producer_era_profile_id,
                required_condition_tags, first_trial_age_adjustment,
                best_start_age_adjustment, best_end_age_adjustment,
                outer_horizon_age_adjustment, body_adjustment, acidity_adjustment,
                tannin_adjustment, sweetness_adjustment, alcohol_adjustment,
                freshness_adjustment, savory_adjustment, concentration_adjustment
            ) values (
                v_profile_id, v_version_id, v_producer_profile_id,
                array(select jsonb_array_elements_text(v_interaction.tags)),
                (v_interaction.adjustment ->> 'first')::integer,
                (v_interaction.adjustment ->> 'bestStart')::integer,
                (v_interaction.adjustment ->> 'bestEnd')::integer,
                (v_interaction.adjustment ->> 'outer')::integer,
                coalesce((v_interaction.traits ->> 'body')::numeric, 0),
                coalesce((v_interaction.traits ->> 'acidity')::numeric, 0),
                coalesce((v_interaction.traits ->> 'tannin')::numeric, 0),
                coalesce((v_interaction.traits ->> 'sweetness')::numeric, 0),
                coalesce((v_interaction.traits ->> 'alcohol')::numeric, 0),
                coalesce((v_interaction.traits ->> 'freshness')::numeric, 0),
                coalesce((v_interaction.traits ->> 'savory')::numeric, 0),
                coalesce((v_interaction.traits ->> 'concentration')::numeric, 0)
            );
            for v_source_key in select jsonb_array_elements_text(v_producer.evidence)
            loop
                perform private.link_hierarchy_profile_evidence(
                    v_profile_id, v_source_key, 'producer-style', 'producer',
                    p_producer_id => v_producer_id, p_wine_color => v_producer.color
                );
            end loop;
            v_profile_id := v_producer_profile_id;
        end loop;
    end loop;

    for v_cuvee in
        select value ->> 'id' as key, value ->> 'producerKey' as producer_key,
               value ->> 'placeId' as place, value ->> 'name' as name,
               value -> 'aliases' as aliases,
               value ->> 'color' as color, value -> 'windowAdjustment' as adjustment,
               value -> 'traits' as traits, (value ->> 'confidence')::numeric as confidence,
               value ->> 'rationale' as rationale, value -> 'evidence' as evidence
        from jsonb_array_elements(v_knowledge -> 'cuvees') seed(value)
    loop
        v_producer_id := private.ensure_hierarchy_producer(
            v_cuvee.producer_key,
            case when v_cuvee.producer_key = 'louis-boillot' then 'Louis Boillot'
                 when v_cuvee.producer_key = 'cal-demoura' then 'Mas Cal Demoura'
                 else v_cuvee.producer_key end
        );
        v_product_id := private.ensure_hierarchy_product(v_cuvee.key, v_producer_id, v_cuvee.name);
        insert into public.wine_reference_aliases (
            id, entity_id, entity_type, alias_value, normalized_value,
            source_name
        )
        select
            private.enrichment_seed_uuid(
                'alias:maturity-v3:product:' || v_cuvee.key || ':' ||
                private.normalize_wine_reference_text(alias.value)
            ),
            v_product_id,
            'product',
            alias.value,
            private.normalize_wine_reference_text(alias.value),
            'maturity-v3'
        from jsonb_array_elements_text(v_cuvee.aliases) alias(value)
        on conflict do nothing;
        v_place_id := private.enrichment_seed_uuid('place:' || v_cuvee.place);
        v_profile_id := private.enrichment_seed_uuid('profile:maturity-v3:cuvee:' || v_cuvee.key);
        insert into public.enrichment_profiles (
            id, knowledge_version_id, profile_type, review_status,
            confidence, rationale, reviewed_at
        ) values (v_profile_id, v_version_id, 'cuvee', 'reviewed',
                  v_cuvee.confidence, v_cuvee.rationale, '2026-08-24T09:00:00Z');
        insert into public.enrichment_cuvee_profiles (
            profile_id, knowledge_version_id, product_id, place_id, wine_color,
            first_trial_age_adjustment, best_start_age_adjustment,
            best_end_age_adjustment, outer_horizon_age_adjustment,
            body_adjustment, acidity_adjustment, tannin_adjustment,
            sweetness_adjustment, alcohol_adjustment, freshness_adjustment,
            savory_adjustment, concentration_adjustment
        ) values (
            v_profile_id, v_version_id, v_product_id, v_place_id, v_cuvee.color,
            (v_cuvee.adjustment ->> 'first')::integer,
            (v_cuvee.adjustment ->> 'bestStart')::integer,
            (v_cuvee.adjustment ->> 'bestEnd')::integer,
            (v_cuvee.adjustment ->> 'outer')::integer,
            coalesce((v_cuvee.traits ->> 'body')::numeric, 0),
            coalesce((v_cuvee.traits ->> 'acidity')::numeric, 0),
            coalesce((v_cuvee.traits ->> 'tannin')::numeric, 0),
            coalesce((v_cuvee.traits ->> 'sweetness')::numeric, 0),
            coalesce((v_cuvee.traits ->> 'alcohol')::numeric, 0),
            coalesce((v_cuvee.traits ->> 'freshness')::numeric, 0),
            coalesce((v_cuvee.traits ->> 'savory')::numeric, 0),
            coalesce((v_cuvee.traits ->> 'concentration')::numeric, 0)
        );
        for v_source_key in select jsonb_array_elements_text(v_cuvee.evidence)
        loop
            perform private.link_hierarchy_profile_evidence(
                v_profile_id, v_source_key, 'cuvee-site', 'product',
                p_product_id => v_product_id, p_wine_color => v_cuvee.color
            );
        end loop;
    end loop;

    for v_release in
        select value ->> 'id' as key, value ->> 'producerKey' as producer_key,
               value ->> 'cuveeId' as cuvee_key, value ->> 'name' as name,
               (value ->> 'vintage')::integer as vintage,
               value -> 'windowAdjustment' as adjustment, value -> 'traits' as traits,
               (value ->> 'confidence')::numeric as confidence,
               value ->> 'rationale' as rationale, value -> 'evidence' as evidence
        from jsonb_array_elements(v_knowledge -> 'releases') seed(value)
    loop
        select value into v_cuvee_json
        from jsonb_array_elements(v_knowledge -> 'cuvees') seed(value)
        where value ->> 'id' = v_release.cuvee_key;
        v_producer_id := private.ensure_hierarchy_producer(
            v_release.producer_key,
            case when v_release.producer_key = 'louis-boillot' then 'Louis Boillot'
                 when v_release.producer_key = 'cal-demoura' then 'Mas Cal Demoura'
                 else v_release.producer_key end
        );
        v_product_id := private.ensure_hierarchy_product(
            v_release.cuvee_key, v_producer_id, v_cuvee_json ->> 'name'
        );
        v_release_id := private.ensure_hierarchy_release(
            v_release.key, v_product_id, v_release.vintage
        );
        v_profile_id := private.enrichment_seed_uuid('profile:maturity-v3:release:' || v_release.key);
        insert into public.enrichment_profiles (
            id, knowledge_version_id, profile_type, review_status,
            confidence, rationale, reviewed_at
        ) values (v_profile_id, v_version_id, 'release', 'reviewed',
                  v_release.confidence, v_release.rationale, '2026-08-24T09:00:00Z');
        insert into public.enrichment_release_profiles (
            profile_id, knowledge_version_id, release_id, wine_color,
            first_trial_age_adjustment, best_start_age_adjustment,
            best_end_age_adjustment, outer_horizon_age_adjustment,
            body_adjustment, acidity_adjustment, tannin_adjustment,
            sweetness_adjustment, alcohol_adjustment, freshness_adjustment,
            savory_adjustment, concentration_adjustment
        ) values (
            v_profile_id, v_version_id, v_release_id, v_cuvee_json ->> 'color',
            (v_release.adjustment ->> 'first')::integer,
            (v_release.adjustment ->> 'bestStart')::integer,
            (v_release.adjustment ->> 'bestEnd')::integer,
            (v_release.adjustment ->> 'outer')::integer,
            coalesce((v_release.traits ->> 'body')::numeric, 0),
            coalesce((v_release.traits ->> 'acidity')::numeric, 0),
            coalesce((v_release.traits ->> 'tannin')::numeric, 0),
            coalesce((v_release.traits ->> 'sweetness')::numeric, 0),
            coalesce((v_release.traits ->> 'alcohol')::numeric, 0),
            coalesce((v_release.traits ->> 'freshness')::numeric, 0),
            coalesce((v_release.traits ->> 'savory')::numeric, 0),
            coalesce((v_release.traits ->> 'concentration')::numeric, 0)
        );
        for v_source_key in select jsonb_array_elements_text(v_release.evidence)
        loop
            perform private.link_hierarchy_profile_evidence(
                v_profile_id, v_source_key, 'maturity-window', 'release',
                p_release_id => v_release_id,
                p_wine_color => v_cuvee_json ->> 'color'
            );
        end loop;
    end loop;

    return public.publish_enrichment_knowledge_version(v_version_id)
        || jsonb_build_object(
            'already_installed', false,
            'place_layer_count', 5,
            'vintage_profile_count', 7,
            'producer_era_count', 3,
            'cuvee_profile_count', 6,
            'release_profile_count', 1
        );
end;
$install$;

comment on function public.install_hierarchical_maturity_knowledge() is
